import perceivo


@perceivo.policy
async def error_handler_policy_internal(input: perceivo.primitives.PolicyInput) -> perceivo.primitives.PolicyOutput:
    rd = input.request_data or {}
    on_exhausted = rd.get("on_exhausted", "fail")
    error = rd.get("error", "Unknown error")
    attempts = rd.get("attempts", 0)

    perceivo.log.info(
        f"Error Handler Policy: action={on_exhausted} after {attempts} attempts",
        error=error,
    )

    return perceivo.primitives.PolicyOutput(
        next_state=on_exhausted,
        response_data={
            "action": on_exhausted,
            "error": error,
            "attempts": attempts,
        },
    )

