import perceivo


@perceivo.adapter
async def error_handler_fallback(input: perceivo.primitives.AdapterInput) -> perceivo.primitives.AdapterOutput:
    """The Error Handler's recovery slot: the safe answer when the primary fails.

    Forwards everything it received and marks the result as recovered, so a
    consumer downstream can tell a fallback answer from a primary one rather
    than having to infer it. Replace it with the real recovery work.
    """
    request_data = input.request_data or {}
    if not isinstance(request_data, dict):
        request_data = {"data": request_data}

    artifact_data = getattr(input.artifact, "data", None) if input.artifact else None
    if isinstance(artifact_data, dict):
        # Explicit request_data wins over artifact-carried values.
        request_data = {**artifact_data, **request_data}

    note = str(
        perceivo.params.get("fallback_note", "Recovered by the Error Handler fallback slot.")
        or "Recovered by the Error Handler fallback slot."
    )
    value = perceivo.params.get("fallback_value", "")

    perceivo.log.info(f"Error Handler Fallback: {note}")
    return perceivo.primitives.AdapterOutput(
        artifact=input.artifact,
        response_data={
            **request_data,
            "fallback_ran": True,
            "fallback_note": note,
            "fallback_value": value,
        },
    )
